 function onlineChange(a,b){const total=c=>c.behavior.mode==='continuous'?'1440':ConnectedCore.multiply(c.behavior.sessionMinutes,String(c.behavior.visitHours.length)),before=total(a),after=total(b);if(a.behavior.mode===b.behavior.mode&&a.behavior.visitHours.length===b.behavior.visitHours.length&&before===after)return'';return before===after?'每天总在线时长相同，但需要更频繁打开。':'每天总在线时长从'+f(before)+'分钟变为'+f(after)+'分钟；进度变化也包含在线时长的影响。';}
 by('cgResults').insertAdjacentHTML('beforeend','<details><summary>管理修改前方案</summary><p>只有当前配置的完整结果能作为新对照。此前配置和结果会保留在导出的历史记录中。</p><button type="button" id="cgFreezeCurrent">用当前完整结果建立新对照</button></details>');by('cgFreezeCurrent').onclick=()=>{if(busy||dirty){notice('先保存并完成当前方案的模拟。',true);return;}const rows=candidateRuns.length?candidateRuns:baseRuns;if(failures.length||rows.length!==game.simulation.seeds.length||rows.some(r=>JSON.stringify(r.inputGame)!==JSON.stringify(game))){notice('当前配置尚无完整匹配结果，请先重新模拟。',true);return;}history.push(copy({game,baseGame,baseRuns,candidateRuns,failures,battleChecks}));baseGame=copy(game);baseRuns=copy(rows);candidateRuns=[];rejected=[];battleChecks=[];by('cgCheckResults').textContent='';renderResults();show('results');notice('当前结果已成为新的修改前方案；旧对照保留在历史中，完整导出可复查。');};
